CREATE TABLE kb.parsing_component (
	task_id BIGINT NOT NULL, 
	component_id TEXT NOT NULL, 
	ordinal BIGINT NOT NULL, 
	category TEXT NOT NULL, 
	representation_id TEXT NOT NULL, 
	unit TEXT NOT NULL, 
	start_offset BIGINT NOT NULL, 
	end_offset BIGINT NOT NULL, 
	CONSTRAINT pk_parsing_component PRIMARY KEY (task_id, component_id), 
	CONSTRAINT uq_parsing_component_task_id_representation_id_ordinal UNIQUE (task_id, representation_id, ordinal), 
	CONSTRAINT ck_parsing_component_physical_c8fe50ca90 CHECK (start_offset >= 0 AND end_offset >= start_offset), 
	CONSTRAINT ck_parsing_component_physical_01f330ec6a CHECK (end_offset > start_offset), 
	CONSTRAINT ck_parsing_component_physical_ee668cd4ef CHECK (ordinal >= 0), 
	CONSTRAINT ck_parsing_component_physical_19f7a1eac4 CHECK (category IN ('markup','text','whitespace','comment','math','reference','unknown'))
);

CREATE TABLE kb.parsing_dependency (
	task_id BIGINT NOT NULL, 
	name TEXT NOT NULL, 
	target_task_id BIGINT NOT NULL, 
	artifact_digest TEXT NOT NULL, 
	CONSTRAINT pk_parsing_dependency PRIMARY KEY (task_id, name), 
	CONSTRAINT uq_parsing_dependency_task_id_name_target_task_id UNIQUE (task_id, name, target_task_id), 
	CONSTRAINT ck_parsing_dependency_physical_5a30b9c6c3 CHECK (task_id <> target_task_id)
);

CREATE TABLE kb.parsing_endpoint (
	task_id BIGINT NOT NULL, 
	relationship_id TEXT NOT NULL, 
	ordinal BIGINT NOT NULL, 
	role TEXT NOT NULL, 
	target_task_id BIGINT NOT NULL, 
	component_id TEXT, 
	node_id TEXT, 
	dependency_name TEXT, 
	CONSTRAINT pk_parsing_endpoint PRIMARY KEY (task_id, relationship_id, ordinal), 
	CONSTRAINT ck_parsing_endpoint_physical_ee668cd4ef CHECK (ordinal >= 0), 
	CONSTRAINT ck_parsing_endpoint_physical_5c00f2717e CHECK ((component_id IS NULL) <> (node_id IS NULL)), 
	CONSTRAINT ck_parsing_endpoint_physical_1009dfb73a CHECK ((task_id = target_task_id AND dependency_name IS NULL) OR (task_id <> target_task_id AND dependency_name IS NOT NULL)), 
	CONSTRAINT ck_parsing_endpoint_physical_2afff5ac3d CHECK (role IN ('parent','child','source','target','invocation','argument','definition','default','fallback','member'))
);

CREATE TABLE kb.parsing_mapping (
	task_id BIGINT NOT NULL, 
	mapping_id TEXT NOT NULL, 
	operation TEXT NOT NULL, 
	reason TEXT NOT NULL, 
	fidelity TEXT NOT NULL, 
	CONSTRAINT pk_parsing_mapping PRIMARY KEY (task_id, mapping_id), 
	CONSTRAINT ck_parsing_mapping_physical_47a94d97c5 CHECK (fidelity IN ('exact','synthetic','excluded','unknown')), 
	CONSTRAINT ck_parsing_mapping_physical_5787eff47e CHECK (operation IN ('decode','normalize','copy','repair','exclude','expand','project','synthetic'))
);

CREATE TABLE kb.parsing_mapping_endpoint (
	task_id BIGINT NOT NULL, 
	mapping_id TEXT NOT NULL, 
	side TEXT NOT NULL, 
	ordinal BIGINT NOT NULL, 
	target_task_id BIGINT NOT NULL, 
	dependency_name TEXT, 
	representation_id TEXT NOT NULL, 
	unit TEXT NOT NULL, 
	start_offset BIGINT NOT NULL, 
	end_offset BIGINT NOT NULL, 
	CONSTRAINT pk_parsing_mapping_endpoint PRIMARY KEY (task_id, mapping_id, side, ordinal), 
	CONSTRAINT ck_parsing_mapping_endpoint_physical_c8fe50ca90 CHECK (start_offset >= 0 AND end_offset >= start_offset), 
	CONSTRAINT ck_parsing_mapping_endpoint_physical_ee668cd4ef CHECK (ordinal >= 0), 
	CONSTRAINT ck_parsing_mapping_endpoint_physical_fb877ed671 CHECK (side IN ('source','target')), 
	CONSTRAINT ck_parsing_mapping_endpoint_physical_1009dfb73a CHECK ((task_id = target_task_id AND dependency_name IS NULL) OR (task_id <> target_task_id AND dependency_name IS NOT NULL))
);

CREATE TABLE kb.parsing_node (
	task_id BIGINT NOT NULL, 
	node_id TEXT NOT NULL, 
	kind TEXT NOT NULL, 
	representation_id TEXT, 
	unit TEXT, 
	start_offset BIGINT, 
	end_offset BIGINT, 
	origin TEXT NOT NULL, 
	origin_reason TEXT, 
	CONSTRAINT pk_parsing_node PRIMARY KEY (task_id, node_id), 
	CONSTRAINT ck_parsing_node_physical_3cb76f16dc CHECK ((origin = 'literal' AND num_nonnulls(representation_id,unit,start_offset,end_offset) = 4 AND origin_reason IS NULL) OR (origin = 'synthetic' AND num_nonnulls(representation_id,unit,start_offset,end_offset) = 0 AND origin_reason IS NOT NULL)), 
	CONSTRAINT ck_parsing_node_physical_c8fe50ca90 CHECK (start_offset >= 0 AND end_offset >= start_offset), 
	CONSTRAINT ck_parsing_node_physical_cda4339865 CHECK (kind IN ('document','element','text','comment','math','group','symbol'))
);

CREATE TABLE kb.parsing_relationship (
	task_id BIGINT NOT NULL, 
	relationship_id TEXT NOT NULL, 
	kind TEXT NOT NULL, 
	CONSTRAINT pk_parsing_relationship PRIMARY KEY (task_id, relationship_id), 
	CONSTRAINT ck_parsing_relationship_physical_917a029008 CHECK (kind IN ('contains','reference','binds','derived_from','sequence'))
);

CREATE TABLE kb.parsing_representation (
	task_id BIGINT NOT NULL, 
	representation_id TEXT NOT NULL, 
	kind TEXT NOT NULL, 
	unit TEXT NOT NULL, 
	extent_length BIGINT NOT NULL, 
	text_content TEXT, 
	partition_state TEXT NOT NULL, 
	recognition_state TEXT NOT NULL, 
	encoding TEXT, 
	decoder TEXT, 
	newline_policy TEXT, 
	CONSTRAINT pk_parsing_representation PRIMARY KEY (task_id, representation_id), 
	CONSTRAINT uq_parsing_representation_task_id_representation_id_unit UNIQUE (task_id, representation_id, unit), 
	CONSTRAINT ck_parsing_representation_physical_667d02ab4e CHECK (kind IN ('original','decoded','canonical','expanded')), 
	CONSTRAINT ck_parsing_representation_physical_0ff456ddac CHECK (unit IN ('byte','codepoint')), 
	CONSTRAINT ck_parsing_representation_physical_cbc06b84d8 CHECK (extent_length >= 0), 
	CONSTRAINT ck_parsing_representation_physical_e132797dbd CHECK ((unit = 'byte' AND kind = 'original' AND text_content IS NULL) OR (unit = 'codepoint' AND kind <> 'original' AND text_content IS NOT NULL AND extent_length = char_length(text_content))), 
	CONSTRAINT ck_parsing_representation_physical_54e2c70939 CHECK (partition_state IN ('complete','partial','unknown','unsupported')), 
	CONSTRAINT ck_parsing_representation_physical_90df5bca14 CHECK (recognition_state IN ('complete','partial','unknown','unsupported')), 
	CONSTRAINT ck_parsing_representation_physical_6f80c55296 CHECK (kind <> 'decoded' OR (encoding IS NOT NULL AND decoder IS NOT NULL AND newline_policy IS NOT NULL))
);

CREATE TABLE kb.source_artifact (
	artifact_digest TEXT NOT NULL, 
	content BYTEA NOT NULL, 
	CONSTRAINT pk_source_artifact PRIMARY KEY (artifact_digest), 
	CONSTRAINT ck_source_artifact_physical_b9e3edc5d9 CHECK (artifact_digest = encode(sha256(content),'hex'))
);

CREATE TABLE ops.parsing_product (
	task_id BIGINT NOT NULL, 
	release_id TEXT NOT NULL, 
	artifact_digest TEXT NOT NULL, 
	contract_digest TEXT NOT NULL, 
	product_digest TEXT NOT NULL, 
	recipe TEXT NOT NULL, 
	lifecycle TEXT NOT NULL, 
	semantic_state TEXT NOT NULL, 
	provenance_state TEXT NOT NULL, 
	payload BYTEA NOT NULL, 
	CONSTRAINT pk_parsing_product PRIMARY KEY (task_id), 
	CONSTRAINT ck_parsing_product_physical_eb4b83c401 CHECK (product_digest = encode(sha256(payload),'hex')), 
	CONSTRAINT ck_parsing_product_physical_9102b3532d CHECK (lifecycle IN ('available','failed','cancelled')), 
	CONSTRAINT ck_parsing_product_physical_2f2c9cf0d1 CHECK (semantic_state IN ('ok','ambiguous','invalid','unsupported','unknown')), 
	CONSTRAINT ck_parsing_product_physical_b9d2c92706 CHECK (provenance_state IN ('complete','partial','unknown','unsupported')), 
	CONSTRAINT ck_parsing_product_physical_027e7e7ef0 CHECK (recipe IN ('source-products-v1'))
);

